def test_dedupe_keeps_last_id_and_sorts():
    events = [
        {"id": "b", "day": 1, "flagged": False},
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "b", "day": 2, "flagged": True},
        {"id": "a", "day": 3, "flagged": True},
