def test_daily_flag_counts_inclusive_range():
    events = [
        {"day": 1, "flagged": True}, {"day": 2, "flagged": None},
        {"day": 3, "flagged": True}, {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [0, 1, 0]
