def test_monitor_summary_rounding_recent_and_active_groups():
    groups = {
        "a": [{"id": "1", "day": 1, "flagged": True}, {"id": "2", "day": 2, "flagged": False}],
        "empty": [],
        "b": [{"id": "3", "day": 2, "flagged": True}],
